const HOUR = 3600;
const MIN_AGE = 12;
const MAX_AGE = 72;

const records = ($input.all() || []).map((item) => item.json).filter((r) => r && typeof r.ts_unix === 'number');

const normUrl = (u) => String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/\/+$/, '').split('?')[0].split('#')[0];

const now = Date.now() / 1000;
const seen = new Set();
const pool = [];
for (const r of records) {
  const age = (now - r.ts_unix) / HOUR;
  if (age < MIN_AGE || age > MAX_AGE) continue;
  const key = normUrl(r.source_url);
  if (!key || seen.has(key)) continue;
  seen.add(key);
  pool.push({ ...r, age_hours: Math.round(age * 10) / 10 });
}

const arr = (f) => pool.map((c) => (c.metrics && c.metrics[f]) || 0);
const vmin = Math.min(...arr('views'), 0);
const vmax = Math.max(...arr('views'), 1);
const lmin = Math.min(...arr('likes'), 0);
const lmax = Math.max(...arr('likes'), 1);
const smin = Math.min(...arr('shares'), 0);
const smax = Math.max(...arr('shares'), 1);
const norm = (v, lo, hi) => (hi === lo ? 1 : (v - lo) / (hi - lo));

for (const c of pool) {
  const m = c.metrics || {};
  const vn = norm(m.views || 0, vmin, vmax);
  const ln = norm(m.likes || 0, lmin, lmax);
  const sn = norm(m.shares || 0, smin, smax);
  c.virality_index = Math.round((vn * 0.4 + ln * 0.3 + sn * 0.3) * 100) / 100;
}

pool.sort((a, b) => b.virality_index - a.virality_index);

const candidates = pool.slice(0, 20).map((c) => ({
  title: c.title,
  source_platform: c.source_platform,
  source_url: c.source_url,
  author: c.author,
  metrics: c.metrics,
  age_hours: c.age_hours,
  virality_index: c.virality_index,
  transcript_excerpt: c.transcript_excerpt,
  feasibility_hint: c.feasibility_hint
}));

const platforms = new Set(records.map((r) => r.source_platform));
const platforms_ok = platforms.size;

return [{ json: {
  candidates,
  meta: { credits_spent: 0, platforms_ok, platforms_failed: 3 - platforms_ok }
} }];

