if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) {} }
if (input && typeof input === 'object' && typeof input.data === 'string') { try { const parsed = JSON.parse(input.data); if (parsed && typeof parsed === 'object') input = parsed; } catch (e) {} }
if (!input) input = {};
const items = (input && Array.isArray(input.reels)) ? input.reels : [];
const out = [];
