  if (typeof r.taken_at === 'number') ts = r.taken_at;
  else if (r.taken_at) ts = Math.floor(Date.parse(r.taken_at) / 1000);
  if (!ts) continue;
  const caption = String(r.caption || '');
  out.push({ json: {
    title: caption,
    source_platform: 'instagram',
    source_url: String(r.url || (r.shortcode ? 'https://www.instagram.com/reel/' + r.shortcode + '/' : '')),
    author: String((r.owner && r.owner.username) || ''),
    metrics: {
      views: Number(r.video_view_count || r.video_play_count || 0),
      likes: Number(r.like_count || 0),
      shares: 0,
      comments: Number(r.comment_count || 0)
    },
    ts_unix: ts,
    transcript_excerpt: caption.slice(0, 200),
    feasibility_hint: 'medium'
  }});
}
