const raw = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
const body = (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) ? raw.body : null;
let balance = null;
try {
  if (body && body.creditCount != null) {
    balance = Number(body.creditCount);
  } else if (raw.creditCount != null) {
    balance = Number(raw.creditCount);
  } else if (typeof raw.data === 'string') {
    balance = Number(JSON.parse(raw.data).creditCount);
  }
} catch (err) {
  balance = null;
}
if (balance == null || !Number.isFinite(balance)) {
  return [{ json: { balance: -1, creditCount: -1, balance_unavailable: true } }];
}
return [{ json: { balance: balance, creditCount: balance, balance_unavailable: false } }];
